export async function recordLoyaltyTransaction(payload: {
  customerPhone: string;
  vehiclePlate: string;
  points: number;
  note?: string;
}) {
  await requireTenantAction("loyalty", "write");
  return { ok: true, ...payload };
}

export async function getWashCustomerDetail(customerKey: string) {
  const { tenantDb, branchId } = await requireTenantAction("customers", "read");
  const [phone, plate] = decodeURIComponent(customerKey).split("|");
  if (!phone || !plate) return null;

  const bookings = await tenantDb
    .select({
      booking: schema.washBookings,
      serviceName: schema.washServices.name,
    })
    .from(schema.washBookings)
    .innerJoin(schema.washServices, eq(schema.washBookings.serviceId, schema.washServices.id))
    .where(
      and(
        eq(schema.washBookings.branchId, branchId),
        eq(schema.washBookings.customerPhone, phone),
        eq(schema.washBookings.vehiclePlate, plate),
      ),
    )
    .orderBy(desc(schema.washBookings.createdAt));

  if (bookings.length === 0) return null;

  const spent = bookings.reduce((s, b) => s + b.booking.amountKes, 0);

  return {
    phone,
    plate,
    visits: bookings.length,
    spent,
    bookings,
  };
}
